using Microsoft.UI.Windowing;
using Microsoft.UI.Xaml;

namespace LogOrganizer.WinUI;

/// <summary>
/// One icon for the exe, the window, the taskbar and the tray, generated by tools/IconGen.
/// Falls back to the executable's embedded icon so a stripped single-file layout still shows a mark.
/// </summary>
internal static class AppIcon
{
    private const int SmCxSmIcon = 49;

    internal static string FilePath => System.IO.Path.Combine(AppContext.BaseDirectory, "Assets", "LogOrganizer.ico");

    /// <summary>Window and taskbar icon. AppWindow.SetIcon needs a path, so a missing file is skipped.</summary>
    internal static void Apply(Window window)
    {
        try
        {
            if (File.Exists(FilePath))
            {
                window.AppWindow.SetIcon(FilePath);
            }
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException)
        {
            CrashLog.Write(ex, "设置窗口图标失败");
        }
    }

    /// <summary>
    /// Tray icon at the shell's small-icon size. Icon picks the closest frame from the .ico, so a
    /// 150% display asks for 24 px and gets the drawn 24 px frame instead of a blurry downscale.
    /// </summary>
    internal static System.Drawing.Icon? CreateTrayIcon()
    {
        var side = NativeMethods.GetSystemMetrics(SmCxSmIcon);
        if (side <= 0)
        {
            side = 16;
        }

        try
        {
            if (File.Exists(FilePath))
            {
                return new System.Drawing.Icon(FilePath, new System.Drawing.Size(side, side));
            }

            var executable = Environment.ProcessPath;
            return string.IsNullOrEmpty(executable) ? null : System.Drawing.Icon.ExtractAssociatedIcon(executable);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException)
        {
            CrashLog.Write(ex, "加载托盘图标失败");
            return null;
        }
    }
}